const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const headers = j.headers || {};
  const header = (name) => headers[name] ?? headers[name.toLowerCase()] ?? headers[name.toUpperCase()] ?? '';
  const parsedFrom =
    j.from && Array.isArray(j.from.value) ? (j.from.value[0] || {}) : {};
  const rawFrom = String(
    parsedFrom.address
      ? ((parsedFrom.name ? parsedFrom.name + ' ' : '') + '<' + parsedFrom.address + '>')
      : (j.from?.text ?? j.from ?? j.From ?? j.fromEmail ?? header('from') ?? '')
  ).trim();
  const fromMatch = rawFrom.match(/^(.*?)\s*<([^>]+)>\s*$/);
  const from_name = String(
    parsedFrom.name ||
      (fromMatch ? fromMatch[1].replace(/^"|"$/g, '').trim() : j.fromName || '')
  ).trim();
  const from_email = String(
    parsedFrom.address || (fromMatch ? fromMatch[2] : rawFrom)
  ).replace(/^<|>$/g, '').trim().toLowerCase();
  const parsedTo =
    j.to && Array.isArray(j.to.value)
      ? j.to.value.map((entry) => entry.address).filter(Boolean)
      : [];
  const rawTo = j.to?.text ?? j.to ?? j.To ?? j.toEmail ?? header('to') ?? '';
  const to = (parsedTo.length
    ? parsedTo
    : (Array.isArray(rawTo) ? rawTo : String(rawTo).split(',')))
    .map((value) => String(value).trim().toLowerCase())
    .filter(Boolean);
  const gmailMessageId = String(j.id || '');
  const message_id = String(j.messageId || header('message-id') || gmailMessageId).trim();
  const thread_id = String(j.threadId || j.thread_id || '') || null;
  const labels = Array.isArray(j.labelIds) ? j.labelIds : [];
  const mailbox = labels.includes('INBOX') ? 'INBOX' : String(j.mailbox || j.label || 'GMAIL');
  const subject = String(j.subject ?? j.Subject ?? header('subject') ?? '(no subject)').trim() || '(no subject)';
  const htmlBody = String(j.html ?? j.textHtml ?? j.textAsHtml ?? '');
  const textBody = String(j.text ?? j.textPlain ?? '');
  let body = textBody || htmlBody || String(j.snippet || '');
  body = body
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>|<\/(p|div|li|tr|blockquote|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .split(/\n\s*On .*wrote:/i)[0]
    .split(/\n\s*-{2,}\s*\n/)[0]
    .replace(/\s+/g, ' ')
    .trim();
  const MAX_BODY = 16000;
  const body_truncated = body.length > MAX_BODY;
  if (body_truncated) body = body.slice(0, MAX_BODY);
  const attachments = Array.isArray(j.attachments) ? j.attachments : [];
  const attachment_metadata = attachments.map((entry) => ({
    filename: String(entry.filename || entry.name || ''),
    mimeType: String(entry.mimeType || entry.type || ''),
    size: Number(entry.size || 0)
  }));
  let hash = 0x811c9dc5;
  for (let index = 0; index < body.length; index += 1) {
    hash ^= body.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  const content_hash = hash.toString(16).padStart(8, '0');
  const correlation_id = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (char) => {
    const random = Math.floor(Math.random() * 16);
    const value = char === 'x' ? random : ((random & 3) | 8);
    return value.toString(16);
  });
  const rawDate = j.date || j.receivedDate || (j.internalDate ? Number(j.internalDate) : null) || header('date');
  const parsedDate = rawDate ? new Date(rawDate) : new Date();
  const received_at = Number.isNaN(parsedDate.getTime()) ? new Date().toISOString() : parsedDate.toISOString();
  const retention_expires_at = new Date(Date.parse(received_at) + 30 * 86400000).toISOString();
  const sourceId = thread_id || gmailMessageId;
  out.push({ json: {
    correlation_id,
    idempotency_key: mailbox + ':' + message_id,
    mailbox,
    message_id,
    gmail_message_id: gmailMessageId,
    thread_id,
    from_name,
    from_email,
    to,
    subject,
    text_body: body,
    received_at,
    attachment_metadata,
    source_link: sourceId ? 'https://mail.google.com/mail/u/0/#inbox/' + sourceId : null,
    content_hash,
    body_truncated,
    oversized_attachments: attachment_metadata.filter((entry) => entry.size > 10485760),
    retention_expires_at,
    list_unsubscribe: String(header('list-unsubscribe') || '')
  } });
}
return out;
